pub(crate) fn compute_search_styles(
    &self,
    engine_state: &EngineState,
    stack: &Stack,
    span: Span,
) -> (Style, Style) {
    let style_computer = StyleComputer::from_config(engine_state, stack);
    let sample = Value::string("search result", span);
    let string_key = if !self.paint_unmatched_prefix && self.highlight_string_key.is_empty() {
        "string"
    } else {
        self.highlight_string_key.as_str()
    };
    let string_style = style_computer.compute(string_key, &sample);
    let highlight_style = style_computer.compute(&self.highlight_result_key, &sample);
    (string_style, highlight_style)
}

fn paint_plain_segment(&self, style: &Style, text: &str) -> String {
    if self.paint_unmatched_prefix {
        style.paint(text).to_string()
    } else {
        text.to_string()
    }
}

fn paint_match_segment(&self, style: &Style, text: &str) -> String {
    if self.paint_unmatched_prefix || !text.is_empty() {
        style.paint(text).to_string()
    } else {
        text.to_string()
    }
}

fn highlight_regex_for_term(&self, needle: &str) -> Result<Regex, ShellError> {
    let regex_string = if !self.paint_unmatched_prefix && needle.is_empty() {
        "(?i)".to_string()
    } else {
        format!("(?i){needle}")
    };
    match Regex::new(&regex_string) {
        Ok(regex) => Ok(regex),
        Err(err) => Err(ShellError::GenericError {
            error: "Could not compile regex".into(),
            msg: err.to_string(),
            span: Some(Span::test_data()),
            help: None,
            inner: vec![],
        }),
    }
}

fn record_has_searchable_column(&self, column: &str, searched_cols: &[&str]) -> bool {
    if searched_cols.is_empty() {
        self.paint_unmatched_prefix
    } else {
        searched_cols.iter().any(|col| *col == column)
    }
}

fn apply_string_highlight(&self, original: &str, highlighted: String, span: Span) -> Value {
    if self.paint_unmatched_prefix || !highlighted.is_empty() {
        Value::string(highlighted, span)
    } else {
        Value::string(original.to_string(), span)
    }
}

pub(crate) fn highlight_search_string(
    &self,
    haystack: &str,
    needle: &str,
    string_style: &Style,
    highlight_style: &Style,
) -> Result<String, ShellError> {
    let regex = self.highlight_regex_for_term(needle)?;
    if haystack.is_empty() && !self.paint_unmatched_prefix {
        return Ok(String::new());
    }
    let stripped_haystack = nu_utils::strip_ansi_likely(haystack);
    let mut last_match_end = 0;
    let mut highlighted = String::new();

    for cap in regex.captures_iter(stripped_haystack.as_ref()) {
        match cap {
            Ok(capture) => {
                let start = match capture.get(0) {
                    Some(acap) => acap.start(),
                    None => 0,
                };
                let end = match capture.get(0) {
                    Some(acap) => acap.end(),
                    None => 0,
                };
                highlighted.push_str(&self.paint_plain_segment(
                    string_style,
                    &stripped_haystack[last_match_end..start],
                ));
                highlighted.push_str(
                    &self.paint_match_segment(highlight_style, &stripped_haystack[start..end]),
                );
                last_match_end = end;
            }
            Err(e) => {
                return Err(ShellError::GenericError {
                    error: "Error with regular expression capture".into(),
                    msg: e.to_string(),
                    span: None,
                    help: None,
                    inner: vec![],
